from configuration import setting
import unittest
class SettingsTests(unittest.TestCase):
    def test_falsey(self):
        for value in [0,False,'',None]:
            with self.subTest(value=value): self.assertEqual(setting({'x':value},'x',99),value)
    def test_missing(self): self.assertEqual(setting({},'x',99),99)
    def test_existing(self): self.assertEqual(setting({'x':7},'x',99),7)
    def test_no_mutation(self):
        x={'a':1};setting(x,'b',3);self.assertEqual(x,{'a':1})

