from statistics_helpers import median
import unittest
class MedianTests(unittest.TestCase):
    def test_even(self): self.assertEqual(median([8,2,4,6]),5)
    def test_odd(self): self.assertEqual(median([8,2,4]),4)
    def test_single(self): self.assertEqual(median([6]),6)
